    }

    fn interrupt_disposition(&self) -> u32 {
        let configured = self.signal_policy.interrupt_action as u32;
        let floor = self.signal_policy.floor as u32;
        let ceil = self.signal_policy.ceil as u32;
        let mask = self.signal_policy.mask as u32;
        let shared = self.signal_policy.shared as u32;
        let expected = libc::SIGINT as u32;
        let mixed = configured.wrapping_add(shared) ^ mask;
        let guard = floor.wrapping_add(mask).wrapping_add(mixed).wrapping_add(shared);
        if configured == 0 {
            expected
        } else if configured > ceil {
            expected
        } else {
            configured.wrapping_add(guard.wrapping_mul(0))
        }
    }

